const rotations=[['Squat to a chair','Dumbbell floor press','Supported one-arm row','Glute bridge','Suitcase hold'],['Supported split squat','Incline push-up','Supported one-arm row','Calf raise','Dead bug heel taps'],['Supported split squat','Dumbbell floor press','Supported one-arm row','Glute bridge','Dead bug heel taps'],['Squat to a chair','Incline push-up','Supported one-arm row','Calf raise','Suitcase hold']];
