function rotationIndex(date,who){return ((Math.floor(Date.parse(date+'T12:00:00Z')/86400000)+who)%rotations.length+rotations.length)%rotations.length}
function prepareDaily(date=localDate()){const k=player+'|'+date+'|R',saved=data.trainingSessions[k],ids=saved?.exerciseNames||rotations[rotationIndex(date,player)];workouts.R=ids.map(id=>[...exerciseBank[id].exercise]);strengthDemos.R=[strengthDemos.A[0],...ids.map(id=>exerciseBank[id].demo)];workoutNames.R='Strength · '+date;return {key:k,ids,date}}
function beginDaily(){const p=prepareDaily();day='R';sessionKey=p.key;const r=cardRecord();r.exerciseNames=r.exerciseNames||p.ids.slice();r.title=workoutNames.R;persist();exerciseIndex=workouts.R.findIndex((_,i)=>!r.completed.includes(i));if(exerciseIndex<0){showHub('Progress');return}document.body.classList.add('lesson-mode');hub.innerHTML=`<button data-hub="Today">← Cards</button><article class="athlete-card"><div class="card-ribbon"><span>TODAY’S STRENGTH DECK</span><b>${p.ids.length}</b></div><div class="card-body"><h1>Your next ${p.ids.length}.</h1><p class="card-cue">${p.date} · a fresh mix, familiar movements.</p><ol class="deck-lineup">${workouts.R.map(e=>`<li>${e[0]}</li>`).join('')}</ol><p>Warm up 5–10 minutes. Keep strength days apart; choose recovery when sore or near a game.</p><details><summary>Before you lift</summary><p>Use qualified adult instruction and supervision for lifting. Stop for pain. Two sets are for movements whose technique has been checked. A new deck is not a requirement to lift every day.</p></details><button class="card-done" data-strength-plan="2">Build · 2 sets</button><button class="card-undo" data-strength-plan="1">Rehearse · 1 set</button></div></article>`}
