let playBeat=0,playFocus='',customPlay=null,playDrag=null;
function currentPlay(){return customPlay||lessonPlays[prefs().focus]||sceneRecipes[Object.keys(sceneGroup).find(k=>sceneGroup[k].includes(prefs().focus))||'receive']}
function playSvg(model,beat){const actors=JSON.parse(JSON.stringify(model.actors));let ball=model.frames[0].ball;for(let i=0;i<=beat;i++){Object.assign(actors,model.frames[i].actors||{});ball=model.frames[i].ball||ball}const f=model.frames[beat],poly=(points,dash)=>`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${dash?'#7c39c7':'#245fd1'}" stroke-width="3" ${dash?'stroke-dasharray="6 5"':''} marker-end="url(#playArrow)"/>`;return `<svg viewBox="0 0 300 240" role="img" aria-label="${escapeHTML(f.text)}"><defs><marker id="playArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="#245fd1"/></marker></defs><rect x="0" y="0" width="300" height="240" rx="16" fill="#f8faff"/><rect x="16" y="16" width="268" height="208" fill="none" stroke="#ccd7e8"/><path d="M16 120H284 M110 16V46H190V16 M110 224V194H190V224" fill="none" stroke="#ccd7e8"/><circle cx="150" cy="120" r="27" fill="none" stroke="#ccd7e8"/>${f.pass?poly(f.pass,false):''}${f.run?poly(f.run,true):''}${Object.entries(actors).map(([id,p])=>`<g class="play-person" transform="translate(${p[0]} ${p[1]})"><circle r="15" fill="${id==='D'||id==='C'&&prefs().focus==='trackrunner'?'#151b2c':'#6c35b3'}" stroke="${id==='D'?'#151b2c':'#c8b2ed'}" stroke-width="2"/><text y="5" text-anchor="middle" fill="${'#fff'}" font-size="13" font-weight="700">${id}</text></g>`).join('')}<circle cx="${ball[0]}" cy="${ball[1]}" r="5" fill="#fff" stroke="#090c14" stroke-width="2"/></svg>`}
function playPanel(){const model=currentPlay();playBeat=Math.min(playBeat,model.frames.length-1);return `<section class="play-panel" tabindex="0" aria-label="Interactive example play">${playSvg(model,playBeat)}<p class="play-caption" aria-live="polite">${model.frames[playBeat].text}</p><div class="play-controls"><button data-play-move="-1" ${playBeat===0?'disabled':''}>←</button><span>${playBeat+1} / ${model.frames.length}</span><button data-play-move="1" ${playBeat===model.frames.length-1?'disabled':''}>Next move →</button><button data-play-reset>↻</button></div><small>A / B: teammates · D: opponent${model.actors.C?prefs().focus==='trackrunner'?' · C: runner to track':' · C: teammate':''}<br>Solid: pass · dashed: movement · swipe to step</small></section>`}
function parsePlay(text){const lines=text.split(/[.\n]+/).map(x=>x.trim()).filter(Boolean);if(!lines.length||lines.length>6)throw Error('Use 1–6 short instructions.');const actors={A:[65,180],B:[180,120],D:[205,75]},frames=[{text:'Your play: starting positions.',ball:[75,170]}];let ball=frames[0].ball,owner='A';for(const line of lines){let m=line.match(/^([ABD])\s+passes to\s+([ABD])$/i);if(m){const a=m[1].toUpperCase(),b=m[2].toUpperCase();if(a===b||owner!==a)throw Error('Only the player with the ball can pass. A starts with it.');const dest=[actors[b][0]+10,actors[b][1]-10];frames.push({text:a+' passes to '+b+'.',ball:dest,pass:[ball.slice(),dest]});ball=dest;owner=b;continue}m=line.match(/^([ABD])\s+(runs|moves)\s+(left|right|up|down)$/i);if(!m)throw Error('Try “A passes to B. A runs right. B passes to A.”');const id=m[1].toUpperCase(),dir=m[3].toLowerCase(),old=actors[id].slice(),dest=[old[0]+(dir==='right'?40:dir==='left'?-40:0),old[1]+(dir==='down'?35:dir==='up'?-35:0)];if(dest[0]<30||dest[0]>270||dest[1]<35||dest[1]>205)throw Error('That move leaves the pitch. Choose another direction.');actors[id]=dest;ball=owner===id?[dest[0]+10,dest[1]-10]:ball;frames.push({text:id+' moves '+dir+'.',actors:{[id]:dest},ball:ball.slice(),run:[old,dest]})}return {actors:{A:[65,180],B:[180,120],D:[205,75]},frames}}
focusStep=function(){clearSessionClock();document.body.classList.add('lesson-mode');const l=lessonById[prefs().focus];if(playFocus!==l.id){playFocus=l.id;playBeat=0;customPlay=null}step=Math.max(0,Math.min(2,step));data.journey.resume[player+'|'+l.id]=step;persist();const phase=['Watch the play','Your call','Take it outside'][step],r=conceptRecord(l.id),m=currentPlay();hub.innerHTML=`<button data-hub="Today">← Home</button><article class="athlete-card iq-play-card"><div class="card-ribbon"><span>GAME IQ / ${phase}</span><b>${step+1}/3</b></div><div class="card-body"><h1>${escapeHTML(l.title)}</h1>${step===0?playPanel():''}${step===1?`<section class="play-panel">${playSvg(m,Math.min(1,m.frames.length-1))}<p class="card-cue">What would you do next? Say why.</p><button data-reveal>Show one useful next move</button><div id="lessonExplanation" hidden>${playSvg(m,m.frames.length-1)}<p>${escapeHTML(m.frames.at(-1).text)}</p></div></section><details><summary>Try another situation</summary><p>${escapeHTML(l.scenario)}</p><p>${escapeHTML(l.answer)}</p></details>`:''}${step===2?`<p class="card-cue">${escapeHTML(l.cues[0])}</p><div class="row"><button data-practice-mode="solo" aria-pressed="${!brotherMode}">Solo</button><button data-practice-mode="brother" aria-pressed="${brotherMode}">With brother</button></div><p>${escapeHTML(brotherMode?l.duo:l.solo)}</p><details><summary>Record what I learned</summary><button data-concept-explain>${r.explained?'✓ Explained':'I explained it without looking'}</button><label>My example<textarea id="conceptExample" maxlength="300">${escapeHTML(r.example||'')}</textarea></label><button data-concept-apply>Save example</button><button data-concept-recall ${!r.explained||r.explained===localDate()?'disabled':''}>Recalled on a later day</button><p id="conceptStatus" role="status">${conceptSecure(l.id)?'Demonstrated':'Use the cue in play. Return when you have an example.'}</p></details>`:''}<details><summary>Watch a real demonstration</summary>${l.video.map(demoLink).join('')}</details><details><summary>Why & match context</summary><p>${escapeHTML(l.why)}</p><p>${escapeHTML(prefs().format==='9'?l.nine:l.eleven)}</p><p>One example, not the only right play. Your coach’s team plan matters.</p></details>${step===0?`<button class="board-builder-launch" data-open-board>✎ Make your own play</button>`:''}<div class="row">${step?'<button data-loop-back>← Back</button>':''}<button class="card-done" ${step===2?'data-loop-finish':'data-next'}>${step===2?'Keep this cue':step===0?'Make a prediction →':'Try it with a ball →'}</button></div></div></article>`;window.scrollTo(0,0)};
const deckHub=showHub;
showHub=function(page='Today'){if(page!=='Today'){deckHub(page);return}appShell(page);const daily=prepareDaily(),l=lessonById[prefs().focus]||lessonById.scan;hub.insertAdjacentHTML('beforeend',`<h1>Choose your deck.</h1><div class="home-decks"><button class="home-deck iq" data-start><small>GAME IQ</small><div class="deck-symbol">A → B</div><h2>${escapeHTML(l.title)}</h2><span>See · choose · try →</span></button><button class="home-deck ball" data-ball-session><small>BALL LAB</small><div class="deck-symbol">◉</div><h2>Touch. Move. Play.</h2><span>3 drill decks →</span></button><button class="home-deck strength" data-daily-strength><small>STRENGTH · ${daily.date}</small><div class="deck-symbol">↟</div><h2>Today’s eight.</h2><span>${daily.ids[0]} + ${daily.ids.length-1} →</span></button></div><p class="quiet-meta">New day, new strength mix. Recovery still comes first.</p><div class="row"><button data-log="Practice">Log practice</button><button data-log="Game">Log game</button></div><details><summary>Profile & training settings</summary><button data-old="strength">Settings & backup</button><button data-parent>Recovery settings</button></details>`)};
const previousBall=ballSession;
ballSession=function(){previousBall();const p=hub.querySelector('.ball-card .card-body>p:not(.card-cue)');if(p){const d=document.createElement('details');d.innerHTML='<summary>Set up the drill</summary>';p.replaceWith(d);d.append(p)}};
function movePlay(delta){playBeat=Math.max(0,Math.min(currentPlay().frames.length-1,playBeat+delta));focusStep()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.dailyStrength!==undefined)beginDaily();if(d.playMove)movePlay(Number(d.playMove));if(d.playReset!==undefined){playBeat=0;focusStep()}if(d.buildPlay!==undefined){try{customPlay=parsePlay($('playDescription').value);playBeat=0;focusStep()}catch(err){$('playError').textContent=err.message}}if(d.originalPlay!==undefined){customPlay=null;playBeat=0;focusStep()}});
document.addEventListener('touchstart',e=>{playDrag=step===0&&e.target.closest('.play-panel')?{x:e.touches[0].clientX,y:e.touches[0].clientY}:null},{passive:true});document.addEventListener('touchend',e=>{if(!playDrag)return;const x=e.changedTouches[0].clientX-playDrag.x,y=e.changedTouches[0].clientY-playDrag.y;playDrag=null;if(Math.abs(x)>50&&Math.abs(x)>Math.abs(y)*1.5)movePlay(x<0?1:-1)},{passive:true});document.addEventListener('keydown',e=>{if(e.target.closest('.play-panel')&&!e.target.closest('button')){if(e.key==='ArrowRight')movePlay(1);if(e.key==='ArrowLeft')movePlay(-1)}});
